from collections import Counter
class Solution:
    def countExcellentPairs(self, nums: List[int], k: int) -> int:
        c = Counter(bin(x).count('1') for x in set(nums))
        ans = 0
        items = sorted(c.items())
        for a, ca in items:
            for b, cb in items:
                if a + b >= k:
                    ans += ca * cb * (2 if a < b else 1)
        return ans

