class Solution {
public:
    long long countExcellentPairs(vector<int>& nums, int k) {
        unordered_set<int> st(nums.begin(), nums.end());
        long long cnt[64] = {};
        for (int x : st) cnt[__builtin_popcount(x)]++;
        long long ans = 0;
        for (int a = 1; a < 64; a++)
            for (int b = 1; b < 64; b++)
                if (a + b >= k)
                    ans += cnt[a] * cnt[b] * (a < b ? 2 : 1);
        return ans;
    }
};

