class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        Set<Integer> st = new HashSet<>();
        for (int x : nums) st.add(x);
        long[] cnt = new long[64];
        for (int x : st) cnt[Integer.bitCount(x)]++;
        long ans = 0;
        for (int a = 1; a < 64; a++)
            for (int b = 1; b < 64; b++)
                if (a + b >= k)
                    ans += cnt[a] * cnt[b] * (a < b ? 2 : 1);
        return ans;
    }
}

