var countExcellentPairs = function(nums, k) {
    const st = new Set(nums);
    const cnt = Array(64).fill(0);
    for (const x of st) cnt[(x.toString(2).match(/1/g) || []).length]++;
    let ans = 0;
    for (let a = 1; a < 64; a++)
        for (let b = 1; b < 64; b++)
            if (a + b >= k)
                ans += cnt[a] * cnt[b] * (a < b ? 2 : 1);
    return ans;
};
